files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  color: #fff;
  font-family: 'Open Sans', sans-serif;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

h1,
h2,
h3,
p {
  margin: 0;
  padding: 0;
}

.quote {
  inline-size: 60%;
  margin: 0;
  padding: 4em;
  font-size: 10px;
  background-color: #5f0dee;
}

.quote__title {
  margin-block-end: 20px;
  font-size: 320%;
  line-height: 150%;
}

.quote__text {
  margin-block-end: 8px;
  font-size: 200%;
  line-height: 150%;
}

.quote__author {
  font-size: 140%;
  line-height: 150%;
}

@media (width <= 768px) {
  .quote {
    inline-size: 100%;
    padding: 2em;
  }
}
